module seq_detector_101_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    output logic detected
);

typedef enum logic [1:0] {S0, S1, S2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    detected = 1'b0;

    case (state)
        S0: if (din) begin
            next_state = S1;
        end else begin
            next_state = S0;
        end

        S1: if (din) begin
            next_state = S1;
        end else begin
            next_state = S2;
        end

        S2: if (din) begin
            next_state = S1;
            detected = 1'b1;  // Sequence "101" detected
        end else begin
            next_state = S0;
        end
    endcase
end

