module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STABLE0;
        counter <= 16'b0;
    end else begin
        state <= next_state;
        if (state == COUNT0 || state == COUNT1)
            counter <= counter + 1;
        else
            counter <= 16'b0;
    end
end

always_comb begin
    next_state = state;
    debounced_out = 1'b0;

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            if (noisy_in)
                next_state = COUNT0;
        end

        COUNT0: begin
            debounced_out = 1'b0;
            if (!noisy_in)
                next_state = STABLE0;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE1;
                debounced_out = 1'b1;  // Output high immediately
            end
        end

        STABLE1: begin
            debounced_out = 1'b1;
            if (!noisy_in)
                next_state = COUNT1;
        end

        COUNT1: begin
            debounced_out = 1'b1;
            if (noisy_in)
                next_state = STABLE1;  // Glitch, go back
            else if (counter == debounce_time - 1) begin
                next_state = STABLE0;
                debounced_out = 1'b0;  // Output low immediately
            end
        end
    endcase
end

