module mesi_cache_controller (
    input logic clk,
    input logic rst_n,
    input logic [31:0] address,
    input logic cpu_read,
    input logic cpu_write,
    input logic bus_read,
    input logic bus_write,
    input logic [1:0] snoop_result,  // 00: HIT, 01: HIT_MODIFIED, 10: SHARED
    output logic [1:0] cache_state,   // 00: M, 01: E, 10: S, 11: I
    output logic bus_request,
    output logic cache_hit,
    output logic flush_cache
);

typedef enum logic [1:0] {
    MODIFIED   = 2'b00,
    EXCLUSIVE  = 2'b01,
    SHARED     = 2'b10,
    INVALID    = 2'b11
} mesi_state_t;

mesi_state_t state, next_state;
logic [31:0] tag_memory;
logic [31:0] current_address;
logic pending_bus_op;
logic [1:0] retry_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= INVALID;
        current_address <= 32'b0;
        pending_bus_op <= 1'b0;
        retry_count <= 2'b0;
    end else begin
        state <= next_state;

        // Update address on new access
        if (cpu_read || cpu_write) begin
            current_address <= address;
            pending_bus_op <= 1'b1;
        end

        // Clear pending operation after completion
        if (bus_read || bus_write)
            pending_bus_op <= 1'b0;

        // Retry logic
        if (state == next_state && state != INVALID && pending_bus_op)
            retry_count <= retry_count + 1;
        else
            retry_count <= 2'b0;
    end
end

always_comb begin
    next_state = state;
    cache_state = state;
    bus_request = 1'b0;
    cache_hit = 1'b0;
    flush_cache = 1'b0;

    // Tag comparison (simplified)
    logic tag_match;
    tag_match = (current_address == tag_memory);

    case (state)
        MODIFIED: begin
            cache_hit = 1'b1;

            // Local CPU access
            if (cpu_read || cpu_write) begin
                // Hit in modified state, no bus transaction needed
                next_state = MODIFIED;
            end

            // Snooped bus transactions
            if (bus_read) begin
                // Need to provide data and transition to shared
                next_state = SHARED;
                bus_request = 1'b1;  // Request bus to provide data
                flush_cache = 1'b1;  // Flush modified data
            end

            if (bus_write) begin
                // Another processor wants to write, invalidate
                next_state = INVALID;
                flush_cache = 1'b1;  // Flush before invalidating
            end

            // Snoop result processing
            unique case (snoop_result)
                2'b01: begin  // HIT_MODIFIED on another cache
                    next_state = SHARED;
                    flush_cache = 1'b1;
                end
                2'b10: begin  // SHARED on another cache
                    next_state = SHARED;
                end
            endcase
        end

        EXCLUSIVE: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = EXCLUSIVE;
            end else if (cpu_write) begin
                // Write to exclusive line -> becomes modified
                next_state = MODIFIED;
            end

            if (bus_read) begin
                // Another processor reading -> becomes shared
                next_state = SHARED;
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        SHARED: begin
            cache_hit = 1'b1;

            if (cpu_read) begin
                next_state = SHARED;
            end else if (cpu_write) begin
                // Write to shared line -> need bus transaction
                next_state = MODIFIED;
                bus_request = 1'b1;  // Request bus for write
            end

            if (bus_write) begin
                // Another processor writing -> invalidate
                next_state = INVALID;
            end
        end

        INVALID: begin
            cache_hit = 1'b0;

            if (cpu_read || cpu_write) begin
                // Miss, need to fetch from memory
                bus_request = 1'b1;

                // Determine next state based on bus response
                if (snoop_result == 2'b10)  // Shared on other cache
                    next_state = SHARED;
                else if (cpu_read)
                    next_state = EXCLUSIVE;
                else if (cpu_write)
                    next_state = MODIFIED;
            end

            // Retry on bus contention
            if (retry_count == 2'b11) begin
                // Force exclusive access after retries
                next_state = EXCLUSIVE;
            end
        end
    endcase

    // Bus arbitration logic
    if (bus_request && (bus_read || bus_write))
        bus_request = 1'b0;  // Clear request when bus is busy
end

